ALTER TABLE public.tasks DROP CONSTRAINT tasks_owner_role_check;
ALTER TABLE public.tasks ADD CONSTRAINT tasks_owner_role_check CHECK (owner_role IN ('GIS','PY','WEB','AI'));
ALTER TABLE public.profiles DROP CONSTRAINT profiles_team_role_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_team_role_check CHECK (team_role IN ('GIS','PY','WEB','AI'));
CREATE TABLE public.project_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 150), kind text NOT NULL CHECK(kind IN ('site','source','layer','analysis','timeline')), site_id text CHECK(site_id IN ('shackleton','malapert')), payload jsonb NOT NULL DEFAULT '{}'::jsonb, provenance jsonb NOT NULL DEFAULT '{}'::jsonb, verification_status text NOT NULL DEFAULT 'pending_verification' CHECK(verification_status IN ('pending_verification','verified')), archived boolean NOT NULL DEFAULT false, updated_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.project_records TO authenticated;
GRANT ALL ON public.project_records TO service_role;
ALTER TABLE public.project_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY "team record reads" ON public.project_records FOR SELECT TO authenticated USING (auth.uid() IS NOT NULL);
CREATE POLICY "team record inserts" ON public.project_records FOR INSERT TO authenticated WITH CHECK(updated_by=auth.uid());
CREATE POLICY "team record updates" ON public.project_records FOR UPDATE TO authenticated USING(auth.uid() IS NOT NULL) WITH CHECK(updated_by=auth.uid());
CREATE TABLE public.project_files (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 255), storage_path text NOT NULL UNIQUE, mime_type text NOT NULL CHECK(mime_type IN ('application/pdf','application/json','text/plain','text/csv','image/png','image/jpeg','image/tiff')), size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760), tags text[] NOT NULL DEFAULT '{}', task_id uuid REFERENCES public.tasks(id), site_id text CHECK(site_id IN ('shackleton','malapert')), record_id uuid REFERENCES public.project_records(id), version integer NOT NULL DEFAULT 1 CHECK(version>0), replaces_id uuid REFERENCES public.project_files(id), review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','reviewed')), archived boolean NOT NULL DEFAULT false, uploaded_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(storage_path LIKE uploaded_by::text || '/%'));
GRANT SELECT,INSERT,UPDATE ON public.project_files TO authenticated;
GRANT ALL ON public.project_files TO service_role;
ALTER TABLE public.project_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY "team file reads" ON public.project_files FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE POLICY "team file inserts" ON public.project_files FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid());
CREATE POLICY "team file updates" ON public.project_files FOR UPDATE TO authenticated USING(auth.uid() IS NOT NULL) WITH CHECK(auth.uid() IS NOT NULL);
CREATE TABLE public.project_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, entity_id uuid NOT NULL, actor_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.project_audit TO authenticated;
GRANT ALL ON public.project_audit TO service_role;
ALTER TABLE public.project_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "team audit reads" ON public.project_audit FOR SELECT TO authenticated USING(auth.uid() IS NOT NULL);
CREATE FUNCTION public.audit_project_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.project_audit(entity_type,entity_id,actor_id,before_data,after_data) VALUES(TG_TABLE_NAME,NEW.id,auth.uid(),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW)); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.audit_project_change() FROM PUBLIC;
CREATE TRIGGER records_audit AFTER INSERT OR UPDATE ON public.project_records FOR EACH ROW EXECUTE FUNCTION public.audit_project_change();
CREATE TRIGGER files_audit AFTER INSERT OR UPDATE ON public.project_files FOR EACH ROW EXECUTE FUNCTION public.audit_project_change();
CREATE POLICY "project file upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='project-files' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('pdf','json','txt','csv','png','jpg','jpeg','tif','tiff'));
CREATE POLICY "project file download" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='project-files' AND EXISTS(SELECT 1 FROM public.project_files f WHERE f.storage_path=name AND NOT f.archived));
CREATE POLICY "project upload cleanup" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='project-files' AND (storage.foldername(name))[1]=auth.uid()::text AND NOT EXISTS(SELECT 1 FROM public.project_files f WHERE f.storage_path=name));